                    "label": label,
                    "attack_type": conv.get("attack_type", "unknown"),
                    "conversation_id": conv["conversation_id"],
                })

    def __len__(self):
        return len(self.conversations)

    def __getitem__(self, idx):
        return self.conversations[idx]
